import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"পরিবেশ সংরক্ষণ আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/46-环境保护法.md","filePath":"bn/46-环境保护法.md"}'),e={name:"bn/46-环境保护法.md"};function i(o,t,h,n,s,b){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="পরিবেশ-সংরক্ষণ-আইন" tabindex="-1">পরিবেশ সংরক্ষণ আইন <a class="header-anchor" href="#পরিবেশ-সংরক্ষণ-আইন" aria-label="Permalink to &quot;পরিবেশ সংরক্ষণ আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>46</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>পরিবেশ সংরক্ষণ, মহাবিশ্বের মূল উৎস, ইকোলজিক্যাল সিম্বায়োসিস, টেকসই উন্নয়ন, দূষণ প্রতিরোধ ও নিয়ন্ত্রণ</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《পরিবেশ সংরক্ষণ আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার পাঁচটি সহায়ক আইনের একটি, এবং এর উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ইকোলজিক্যাল পরিবেশ এবং মহাবিশ্বের মূল উৎস সংরক্ষণ করা, &quot;সিম্বায়োসিস বিবর্তন, টেকসই উন্নয়ন&quot; এর পরিবেশ শাসনের দর্শন প্রতিষ্ঠা করা, লুঠেরা উন্নয়নের মাধ্যমে মহাবিশ্বের ইকোলজিক্যাল সিস্টেমের ধ্বংস প্রতিরোধ করা, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য বেঁচে থাকার ভিত্তি রক্ষা করা।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>মূল উৎস সংরক্ষণ নীতি</td><td>মহাবিশ্বের মূল উৎস হল সমস্ত জীবন এবং বিবর্তনের ভিত্তি, অবশ্যই অগ্রাধিকারে সংরক্ষণ করতে হবে, এবং ধ্বংসাত্মক খনন নিষিদ্ধ</td></tr><tr><td>ইকোলজিক্যাল সিম্বায়োসিস নীতি</td><td>মানব এবং প্রকৃতি, প্রতিটি প্রজাতি এবং ইকোলজিক্যাল সিস্টেম হল সিম্বায়োসিস সম্পর্ক, এবং ইকোলজি ধ্বংস করা নিজের বেঁচে থাকার ভিত্তি ধ্বংস করা</td></tr><tr><td>টেকসই নীতি</td><td>সমস্ত উন্নয়ন কার্যক্রম অবশ্যই বর্তমান এবং ভবিষ্যৎ প্রজন্মের স্বার্থ একসাথে বিবেচনা করতে হবে, এবং অতিরিক্ত ব্যবহারের বিরোধিতা করা</td></tr><tr><td>প্রতিরোধ প্রধান নীতি</td><td>পরিবেশ সংরক্ষণ প্রতিরোধকে প্রধান করে, পরিবেশ প্রভাব মূল্যায়ন ব্যবস্থা স্থাপন করে, এবং দূষণ ঘটনা প্রতিরোধ করে</td></tr><tr><td>দূষণকারী দায়বদ্ধতা নীতি</td><td>পরিবেশ দূষণ এবং ইকোলজিক্যাল ধ্বংস সৃষ্টিকারী বস্তুকে অবশ্যই শোধন এবং ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ করতে হবে</td></tr><tr><td>জনগণের অংশগ্রহণ নীতি</td><td>জনগণকে পরিবেশ সংরক্ষণে অংশগ্রহণ করতে উৎসাহিত করা, জনগণের পরিবেশ সম্পর্কে জানার অধিকার এবং অংশগ্রহণের অধিকার নিশ্চিত করা</td></tr><tr><td>আন্তঃ位面 সহযোগিতা নীতি</td><td>পরিবেশ সংরক্ষণ আন্তঃ位面 সহযোগিতার মাধ্যমে এগিয়ে যায়, আন্তঃ位面 পরিবেশ শাসন সহযোগিতা ব্যবস্থা স্থাপন করা</td></tr></tbody></table><h2 id="_2-পরিবেশ-সংরক্ষণের-পরিসর" tabindex="-1">2. পরিবেশ সংরক্ষণের পরিসর <a class="header-anchor" href="#_2-পরিবেশ-সংরক্ষণের-পরিসর" aria-label="Permalink to &quot;2. পরিবেশ সংরক্ষণের পরিসর&quot;">​</a></h2><p>এই আইন দ্বারা সংরক্ষিত পরিবেশের পরিসরে হেঙ্গুয়ানঝৌর ভেতরের সমস্ত ইকোলজিক্যাল সিস্টেম এবং পরিবেশের উপাদান অন্তর্ভুক্ত:</p><ol><li><strong>বায়ু পরিবেশ</strong>: প্রতিটি গ্রহের বায়ুমণ্ডল, শক্তি স্তরের শক্তির ঘনত্ব এবং উপাদানের ভারসাম্য অন্তর্ভুক্ত।</li><li><strong>জল পরিবেশ</strong>: ভূপৃষ্ঠের জল, ভূগর্ভস্থ জল, সমুদ্র,位面ের মধ্যে শক্তির জলাভূমির পানির মান এবং পানির পরিমাণ অন্তর্ভুক্ত।</li><li><strong>মাটি পরিবেশ</strong>: স্থলভাগের মাটি, সাধনা সম্পদের খনির শিরার মাটির গুণমান এবং উর্বরতা অন্তর্ভুক্ত।</li><li><strong>জীববৈচিত্র্য</strong>: সমস্ত গাছপালা এবং প্রাণী, অণুজীব, অদ্ভুত জীবনের প্রজাতি সংরক্ষণ এবং বাসস্থান সংরক্ষণ অন্তর্ভুক্ত।</li><li><strong>শক্তি পরিবেশ</strong>: আকাশ-পৃথিবীর আত্মিক শক্তি, মূল উৎসের শক্তি, নিয়মের টুকরোর ঘনত্ব এবং বিতরণের ভারসাম্য অন্তর্ভুক্ত।</li><li><strong>স্থান পরিবেশ</strong>:位面 স্থানের স্থিতিশীলতা, স্থানের ফাটল, ভাঁজ করা স্থানের পরিবেশের নিরাপত্তা অন্তর্ভুক্ত।</li><li><strong>চেতনা অঞ্চলের পরিবেশ</strong>: সম্মিলিত চেতনা স্থানের তথ্যের পরিচ্ছন্নতা এবং মানসিক দূষণ প্রতিরোধ অন্তর্ভুক্ত।</li></ol><h2 id="_3-প্রধান-ব্যবস্থা" tabindex="-1">3. প্রধান ব্যবস্থা <a class="header-anchor" href="#_3-প্রধান-ব্যবস্থা" aria-label="Permalink to &quot;3. প্রধান ব্যবস্থা&quot;">​</a></h2><h3 id="ক-পরিবেশ-প্রভাব-মূল্যায়ন-ব্যবস্থা" tabindex="-1">(ক) পরিবেশ প্রভাব মূল্যায়ন ব্যবস্থা <a class="header-anchor" href="#ক-পরিবেশ-প্রভাব-মূল্যায়ন-ব্যবস্থা" aria-label="Permalink to &quot;(ক) পরিবেশ প্রভাব মূল্যায়ন ব্যবস্থা&quot;">​</a></h3><p>সমস্ত সম্ভাব্য পরিবেশে গুরুতর প্রভাব ফেলতে পারে এমন উন্নয়ন ও নির্মাণ প্রকল্প, কাজ শুরু করার আগে অবশ্যই পরিবেশ প্রভাব মূল্যায়ন করতে হবে। মূল্যায়নের বিষয়বস্তু অন্তর্ভুক্ত: প্রকল্পের বায়ু, জল, মাটি, জীব, শক্তি, স্থান ইত্যাদি পরিবেশের উপাদানের উপর প্রভাব, প্রতিরোধ এবং হ্রাসের ব্যবস্থা, পরিবেশ ঝুঁকি মূল্যায়ন ইত্যাদি। পরিবেশ প্রভাব মূল্যায়নে পাস না করা প্রকল্প কাজ শুরু করতে পারবে না।</p><h3 id="খ-দূষণ-নিষ্কাশন-লাইসেন্স-এবং-মোট-পরিমাণ-নিয়ন্ত্রণ-ব্যবস্থা" tabindex="-1">(খ) দূষণ নিষ্কাশন লাইসেন্স এবং মোট পরিমাণ নিয়ন্ত্রণ ব্যবস্থা <a class="header-anchor" href="#খ-দূষণ-নিষ্কাশন-লাইসেন্স-এবং-মোট-পরিমাণ-নিয়ন্ত্রণ-ব্যবস্থা" aria-label="Permalink to &quot;(খ) দূষণ নিষ্কাশন লাইসেন্স এবং মোট পরিমাণ নিয়ন্ত্রণ ব্যবস্থা&quot;">​</a></h3><p>রাষ্ট্র দূষক পদার্থ নিষ্কাশনের জন্য লাইসেন্স ব্যবস্থাপনা এবং মোট পরিমাণ নিয়ন্ত্রণ চালু করে। দূষণ নিষ্কাশনকারী ইউনিটকে অবশ্যই দূষণ নিষ্কাশন লাইসেন্স পেতে হবে, এবং লাইসেন্সে নির্ধারিত প্রকার, ঘনত্ব, মোট পরিমাণ অনুযায়ী দূষক পদার্থ নিষ্কাশন করতে হবে। রাষ্ট্র পরিবেশের বহন ক্ষমতা অনুযায়ী প্রতিটি অঞ্চল, প্রতিটি位面ের দূষক পদার্থ নিষ্কাশনের মোট পরিমাণ নির্ধারণ করে, এবং ধাপে ধাপে বিভক্ত করে বাস্তবায়ন করে।</p><h3 id="গ-ইকোলজিক্যাল-সংরক্ষণ-লাল-রেখা-ব্যবস্থা" tabindex="-1">(গ) ইকোলজিক্যাল সংরক্ষণ লাল রেখা ব্যবস্থা <a class="header-anchor" href="#গ-ইকোলজিক্যাল-সংরক্ষণ-লাল-রেখা-ব্যবস্থা" aria-label="Permalink to &quot;(গ) ইকোলজিক্যাল সংরক্ষণ লাল রেখা ব্যবস্থা&quot;">​</a></h3><p>রাষ্ট্র বিশেষ ইকোলজিক্যাল মূল্যসম্পন্ন অঞ্চলে ইকোলজিক্যাল সংরক্ষণ লাল রেখা চিহ্নিত করে, এবং এর মধ্যে অন্তর্ভুক্ত:</p><table tabindex="0"><thead><tr><th>লাল রেখার ধরন</th><th>সংরক্ষণের বিষয়বস্তু</th></tr></thead><tbody><tr><td>মূল উৎস সংরক্ষণ অঞ্চল</td><td>মহাবিশ্বের মূল উৎস শক্তির মূল উৎপাদন অঞ্চল, সমস্ত উন্নয়ন কার্যক্রম নিষিদ্ধ</td></tr><tr><td>প্রজাতির বাসস্থান</td><td>বিরল বিপন্ন প্রজাতির মূল বাসস্থান, ধ্বংস এবং হস্তক্ষেপ নিষিদ্ধ</td></tr><tr><td>ইকোলজিক্যাল বাধা অঞ্চল</td><td>আঞ্চলিক ইকোলজিক্যাল ভারসাম্য বজায় রাখার গুরুত্বপূর্ণ ইকোলজিক্যাল সিস্টেম, উন্নয়ন সীমিত</td></tr><tr><td>সাধনা পবিত্র স্থান</td><td>বিশেষ সাধনা মূল্যসম্পন্ন শক্তি সমৃদ্ধ অঞ্চল, সংরক্ষণমূলক ব্যবহার চালু</td></tr><tr><td>位面 সংযোগ অঞ্চল</td><td>位面ের মধ্যে ইকোলজিক্যাল সংক্রমণ অঞ্চল, স্থান ধ্বংসাত্মক উন্নয়ন নিষিদ্ধ</td></tr></tbody></table><h3 id="ঘ-পরিবেশ-পর্যবেক্ষণ-এবং-সতর্কতা-ব্যবস্থা" tabindex="-1">(ঘ) পরিবেশ পর্যবেক্ষণ এবং সতর্কতা ব্যবস্থা <a class="header-anchor" href="#ঘ-পরিবেশ-পর্যবেক্ষণ-এবং-সতর্কতা-ব্যবস্থা" aria-label="Permalink to &quot;(ঘ) পরিবেশ পর্যবেক্ষণ এবং সতর্কতা ব্যবস্থা&quot;">​</a></h3><p>রাষ্ট্র সমগ্র মহাবিশ্ব জুড়ে পরিবেশ পর্যবেক্ষণ নেটওয়ার্ক স্থাপন করে, এবং প্রতিটি পরিবেশের উপাদানের পরিবর্তনের পরিস্থিতি রিয়েল-টাইমে পর্যবেক্ষণ করে। সম্ভাব্য গুরুতর পরিবেশ দূষণ এবং ইকোলজিক্যাল ধ্বংসের ঘটনার জন্য, সতর্কতা ব্যবস্থা স্থাপন করে, সময়মতো সতর্কতা তথ্য প্রকাশ করে এবং জরুরী প্রতিক্রিয়া শুরু করে।</p><h3 id="ঙ-ইকোলজিক্যাল-ক্ষতিপূরণ-ব্যবস্থা" tabindex="-1">(ঙ) ইকোলজিক্যাল ক্ষতিপূরণ ব্যবস্থা <a class="header-anchor" href="#ঙ-ইকোলজিক্যাল-ক্ষতিপূরণ-ব্যবস্থা" aria-label="Permalink to &quot;(ঙ) ইকোলজিক্যাল ক্ষতিপূরণ ব্যবস্থা&quot;">​</a></h3><p>পরিবেশ সংরক্ষণের কারণে উন্নয়ন সীমিত অঞ্চল এবং গোষ্ঠীর, ইকোলজিক্যাল ক্ষতিপূরণ পাওয়ার অধিকার রয়েছে। ইকোলজিক্যাল ক্ষতিপূরণের তহবিল পাবলিক সঞ্চয় এবং সম্পদ উন্নয়নের আয় থেকে বহন করা হয়, এবং ক্ষতিপূরণ অঞ্চলের আর্থিক উন্নয়ন এবং বাসিন্দাদের জীবনযাত্রার উন্নতির জন্য ব্যবহৃত হয়।</p><h2 id="_4-সাধনা-কার্যক্রমের-পরিবেশ-নিয়ন্ত্রণ" tabindex="-1">4. সাধনা কার্যক্রমের পরিবেশ নিয়ন্ত্রণ <a class="header-anchor" href="#_4-সাধনা-কার্যক্রমের-পরিবেশ-নিয়ন্ত্রণ" aria-label="Permalink to &quot;4. সাধনা কার্যক্রমের পরিবেশ নিয়ন্ত্রণ&quot;">​</a></h2><p>সাধনা কার্যক্রমের পরিবেশের উপর প্রভাব হল হেঙ্গুয়ানঝৌর পরিবেশ সংরক্ষণের বিশেষ ক্ষেত্র, এবং এই আইন বিশেষভাবে নিয়ন্ত্রণের ধারা স্থাপন করে:</p><ol><li><strong>শক্তি খনন নিয়ন্ত্রণ</strong>: সাধনা সম্পদের খনন অবশ্যই টেকসই নীতি পূরণ করতে হবে, এবং ধ্বংসাত্মক খনন যা শক্তির ক্ষয় ঘটায় তা নিষিদ্ধ। খননের পরিমাণ অঞ্চলের শক্তির প্রাকৃতিক পুনরুদ্ধারের গতি অতিক্রম করতে পারবে না।</li><li><strong>সাধনা বর্জ্য পরিচালনা</strong>: সাধনার প্রক্রিয়ায় উৎপন্ন শক্তির অবশিষ্টাংশ, বর্জ্য ওষুধ, ক্ষতিগ্রস্ত যন্ত্র ইত্যাদি অবশ্যই নির্ধারিত অনুযায়ী পরিচালনা করতে হবে, এবং অনিয়মিতভাবে ফেলে দিয়ে শক্তি দূষণ সৃষ্টি করা নিষিদ্ধ।</li><li><strong>উচ্চস্তরের সাধনা পরিবেশ মূল্যায়ন</strong>: উচ্চস্তরের সাধকের অগ্রগতি এবং অন্তর্ভুক্তি আশেপাশের পরিবেশে গুরুতর প্রভাব ফেলতে পারে, এবং অবশ্যই আগে পরিবেশ মূল্যায়ন করতে হবে এবং সুরক্ষা ব্যবস্থা গ্রহণ করতে হবে।</li><li><strong>位面 উন্নয়ন লাইসেন্স</strong>: নতুন位面ের উন্নয়ন অবশ্যই পরিবেশ মূল্যায়ন এবং ইকোলজিক্যাল তদন্তের মধ্য দিয়ে যেতে হবে, এবং ইকোলজিক্যাল সংরক্ষণ পরিকল্পনা তৈরি করার পরেই চালানো যাবে।</li><li><strong>অদ্ভুত জীবনের বাসস্থান সংরক্ষণ</strong>: অদ্ভুত জীবনের বাসস্থান ইকোলজিক্যাল সংরক্ষণ লাল রেখায় অন্তর্ভুক্ত, এবং লাইসেন্স ছাড়া অন্বেষণ এবং উন্নয়ন নিষিদ্ধ।</li></ol><h2 id="_5-আইনি-দায়বদ্ধতা" tabindex="-1">5. আইনি দায়বদ্ধতা <a class="header-anchor" href="#_5-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;5. আইনি দায়বদ্ধতা&quot;">​</a></h2><p>এই আইনের বিধান লঙ্ঘন করা কার্যক্রম, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ul><li>পরিবেশ প্রভাব মূল্যায়নে পাস না করে অনিয়মিতভাবে কাজ শুরু করলে, নির্মাণ বন্ধ করার নির্দেশ, আসল অবস্থায় ফিরিয়ে দেওয়া এবং জরিমানা।</li><li>মানদণ্ড অতিক্রম করে দূষক পদার্থ নিষ্কাশন করলে, নির্ধারিত সময়ের মধ্যে শোধন করার নির্দেশ এবং জরিমানা, গুরুতর অপরাধের ক্ষেত্রে ব্যবসা বন্ধ করে দেওয়ার নির্দেশ।</li><li>ইকোলজিক্যাল সংরক্ষণ লাল রেখা ধ্বংস করলে, আসল অবস্থায় ফিরিয়ে দেওয়ার নির্দেশ এবং জরিমানা, গুরুতর অপরাধের ক্ষেত্রে ফৌজদারি দায়বদ্ধতা আরোপ।</li><li>সাধনা সম্পদের ধ্বংসাত্মক খনন করলে, অবৈধ আয় জব্দ এবং জরিমানা, খনন লাইসেন্স বাতিল।</li><li>গুরুতর পরিবেশ দূষণ দুর্ঘটনা সৃষ্টি করলে, ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ, অপরাধ গঠন করলে ফৌজদারি দায়বদ্ধতা আরোপ।</li><li>পরিবেশ তদারকি কর্মী অবহেলা করলে, ক্ষমতার অপব্যবহার করলে, শাস্তি দেওয়া হবে, অপরাধ গঠন করলে ফৌজদারি দায়বদ্ধতা আরোপ।</li></ul><h2 id="_6-জনগণের-অংশগ্রহণ-এবং-পরিবেশ-জনকল্যাণ-মামলা" tabindex="-1">6. জনগণের অংশগ্রহণ এবং পরিবেশ জনকল্যাণ মামলা <a class="header-anchor" href="#_6-জনগণের-অংশগ্রহণ-এবং-পরিবেশ-জনকল্যাণ-মামলা" aria-label="Permalink to &quot;6. জনগণের অংশগ্রহণ এবং পরিবেশ জনকল্যাণ মামলা&quot;">​</a></h2><p>জনগণের পরিবেশ সংরক্ষণে অংশগ্রহণ করার অধিকার রয়েছে, এবং নির্দিষ্ট উপায় অন্তর্ভুক্ত:</p><ol><li>পরিবেশ প্রভাব মূল্যায়ন প্রকল্পে মতামত এবং পরামর্শ প্রদান করা।</li><li>পরিবেশ দূষণ এবং ইকোলজি ধ্বংসের কার্যক্রমের বিরুদ্ধে অভিযোগ এবং তদন্ত করা।</li><li>আইন অনুযায়ী পরিবেশ সংরক্ষণ সংস্থা গঠন করা, পরিবেশ তদারকি এবং জনকল্যাণ কার্যক্রমে অংশগ্রহণ করা।</li><li>পরিবেশ দূষণ, ইকোলজি ধ্বংস যা জনকল্যাণের স্বার্থ ক্ষতিগ্রস্ত করে, সেক্ষেত্রে পরিবেশ সংরক্ষণ সংস্থা সিম্বায়োসিস আদালতে পরিবেশ জনকল্যাণ মামলা দায়ের করতে পারে।</li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《পরিবেশ সংরক্ষণ আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার টেকসই উন্নয়নের দর্শনের আইনি নিশ্চয়তা। এটি পরিবেশ প্রভাব মূল্যায়ন, ইকোলজিক্যাল সংরক্ষণ লাল রেখা, মোট পরিমাণ নিয়ন্ত্রণ ইত্যাদি ব্যবস্থা স্থাপন করার মাধ্যমে, পরিবেশ সংরক্ষণকে সমস্ত উন্নয়ন এবং সাধনা কার্যক্রমে মিশিয়ে দেয়, এবং মহাবিশ্বের মূল উৎস এবং ইকোলজিক্যাল সিস্টেমের টেকসইতা নিশ্চিত করে, সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য চিরন্তন বেঁচে থাকার ভিত্তি রক্ষা করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>39-住房与环境保障 (আবাসন এবং পরিবেশ নিশ্চয়তা)</li><li>15-能量循环与转化法则 (শক্তি চক্র এবং রূপান্তরের নিয়ম)</li><li>53-奇特生命识别标准 (অদ্ভুত জীবন শনাক্তকরণের মানদণ্ড)</li></ul>',34)])])}const u=a(e,[["render",i]]);export{_ as __pageData,u as default};
